using System;using System.Linq;using System.Threading;namespace ServiceTool{internal static class ServiceLiveAuditTests{[STAThread]static int Main(){int failures=0;foreach(string name in new[]{"DK.Banking.Agent","DK.Scanner.Agent","DK.License.Service.Host","Bars.Mobile.CashDesk.Service","Bars.WebStore.Service","Bars.Mobile.Service"}){try{var info=ServiceEndpoints.Inspect(name);Console.WriteLine("SERVICE "+name+" PID="+info.Pid+" listeners="+info.Listeners.Count+" checks="+info.Checks.Count);foreach(var url in info.Checks){var result=ServiceProbe.Check(url,CancellationToken.None,2000);Console.WriteLine(url+" => "+result.Responded+" "+result.Message);}Console.WriteLine("Swagger: "+(ServiceSwagger.Find(info.HttpAddresses,CancellationToken.None)??"not discovered"));}catch(Exception e){failures++;Console.WriteLine(name+": "+e.GetType().Name+" "+e.Message);}}Console.WriteLine("Live read-only audit completed; no service registration/start/stop or business calls.");return failures==0?0:1;}}}